Here is the commit message:
NFS: Automounted filesystems should inherit
 ro,noexec,nodev,sync flags

When a filesystem is being automounted, it needs to preserve the
user-set superblock mount options, such as the "ro" flag.

Reported-by: Li Lingfeng <lilingfeng3@huawei.com>
Link: https://lore.kernel.org/all/20240604112636.236517-3-lilingfeng@huaweicloud.com/
Fixes: f2aedb713c28 ("NFS: Add fs_context support.")
Signed-off-by: Trond Myklebust <trond.myklebust@hammerspace.com>

Here is the root cause:
The automount path in `nfs_d_automount()` (in `fs/nfs/namespace.c`) did not propagate the parent superblock's mount flags (`ro`, `noexec`, `nodev`, `sync`, etc.) to the new filesystem context. The only attempt at flag inheritance was in `nfs_get_tree_common()` (`fs/nfs/super.c`), which was incomplete—it only handled `SB_SYNCHRONOUS` and only when cloning a superblock via `ctx->clone_data.sb`. This left other critical flags unset for automounted subdirectories, causing the bug.

Here is the patch:
  */
 struct vfsmount *nfs_d_automount(struct path *path)
 {
 	struct nfs_fs_context *ctx;
 	struct fs_context *fc;
 	struct vfsmount *mnt = ERR_PTR(-ENOMEM);
 	struct nfs_server *server = NFS_SB(path->dentry->d_sb);
 	struct nfs_client *client = server->nfs_client;
+	unsigned long s_flags = path->dentry->d_sb->s_flags;
 	int timeout = READ_ONCE(nfs_mountpoint_expiry_timeout);
 	int ret;

 	if (IS_ROOT(path->dentry))
 		return ERR_PTR(-ESTALE);

 	/* Open a new filesystem context, transferring parameters from the
 	 * parent superblock, including the network namespace.
 	 */
 	fc = fs_context_for_submount(path->mnt->mnt_sb->s_type, path->dentry);
 	if (IS_ERR(fc))
 		return ERR_CAST(fc);

 	ctx = nfs_fc2context(fc);
 	ctx->clone_data.dentry	= path->dentry;
 	ctx->clone_data.sb	= path->dentry->d_sb;
 	ctx->clone_data.fattr	= nfs_alloc_fattr();
 	if (!ctx->clone_data.fattr)
 		goto out_fc;

 	if (fc->net_ns != client->cl_net) {
 		put_net(fc->net_ns);
 		fc->net_ns = get_net(client->cl_net);
 	}

+	/* Inherit the flags covered by NFS_SB_MASK */
+	fc->sb_flags_mask |= NFS_SB_MASK;
+	fc->sb_flags &= ~NFS_SB_MASK;
+	fc->sb_flags |= s_flags & NFS_SB_MASK;
+
 	/* for submounts we want the same server; referrals will reassign */
 	memcpy(&ctx->nfs_server._address, &client->cl_addr, client->cl_addrlen);
 	ctx->nfs_server.addrlen	= client->cl_addrlen;
 	ctx->nfs_server.port	= server->port;

 	ctx->version		= client->rpc_ops->version;
 	ctx->minorversion	= client->cl_minorversion;
 	ctx->nfs_mod		= client->cl_nfs_mod;
 	get_nfs_version(ctx->nfs_mod);

 	ret = client->rpc_ops->submount(fc, server);
 	if (ret < 0) {
 		mnt = ERR_PTR(ret);
 		goto out_fc;
 	}

 	up_write(&fc->root->d_sb->s_umount);
 	mnt = vfs_create_mount(fc);
 	if (IS_ERR(mnt))
 		goto out_fc;

 	if (timeout <= 0)
 		goto out_fc;

 	mnt_set_expiry(mnt, &nfs_automount_list);
 	schedule_delayed_work(&nfs_automount_task, timeout);

 out_fc:
 	put_fs_context(fc);
 	return mnt;
 }



